-- 039: Weltereignisse (einmalig, verändern die Welt für alle). Erzeugt von quests/g4.py
insert into public.quest_templates (id, titel, beschreibung, kurz, art, schwierigkeit, rollen, def, fundort)
select e->>'id', e->>'titel', e->>'kurz', e->>'kurz', 'welt', (e->>'schwer')::int, '{}'::jsonb, e->'def', e->>'fundort' from jsonb_array_elements($q$[{"id": "w_nacht_der_raben", "titel": "Die Nacht der Raben", "kurz": "In Rabenfels liegt der alte Graf im Sterben, und sein Vogt hat das Tor zum Turm verschlossen. Was in dieser Nacht geschieht, verändert die Grafschaft – für alle.", "schwer": 3, "fundort": "rabenfels", "def": {"start": "start", "szenen": {"start": {"ort": "burg", "text": "Rabenfels liegt unter einer Glocke aus Rauch. Auf den Gassen brennen Kleider von Fieberkranken, die Wachen tragen Tücher vor dem Mund. Als du durchs Tor kommst, läuten oben auf der Burg die Glocken – nicht zum Gottesdienst, sondern langsam, schwer. Eine Magd rennt an dir vorbei, es ist Wiebke aus der Burgküche. Sie erkennt dich nicht, aber sie keucht: „Der Graf hat das Fieber. Und der Vogt hat das Tor zum Turm schließen lassen.“", "optionen": [{"text": "Wiebke hinterherlaufen", "weiter": "wiebke"}, {"text": "Zur Burgkapelle, zu Kaplan Severin", "weiter": "severin"}, {"text": "Im Dorf unter dem Felsen herumhören", "weiter": "dorf"}]}, "dorf": {"ort": "dorf", "text": "In der Schenke unter dem Felsen sitzen Männer, die nicht trinken. „Ragnolf hat heute Mittag Graumäntel durchs Tor gelassen“, flüstert einer. „Zwanzig, vielleicht mehr. Wozu braucht man Meuchler, wenn der Graf ohnehin stirbt?“ Ein anderer: „Damit Gerlinde nicht rechtzeitig kommt. Die Tochter. Sie ist im Kloster Morgenstern. Wenn der Graf stirbt, bevor sie hier ist, nimmt sich der Vogt den Stuhl.“", "optionen": [{"text": "Zur Burg, zu Wiebke", "weiter": "wiebke", "folgen": {"flag": ["graumaentel_gehoert"]}}, {"text": "Zur Kapelle, zu Severin", "weiter": "severin", "folgen": {"flag": ["graumaentel_gehoert"]}}]}, "wiebke": {"ort": "burg", "text": "Wiebke zieht dich in einen Vorratskeller. „Der Graf liegt oben im Turm. Ragnolf lässt niemanden zu ihm, nicht einmal den Bader. Er sagt, wegen der Ansteckung.“ Sie dreht ihre Schürze in den Händen. „Ich habe ihm heute die Suppe gebracht. Er hat kaum Fieber gehabt. Er hat gezittert und sich übergeben. Das ist kein Fleckfieber, das ist etwas anderes.“", "optionen": [{"text": "Fragen, was genau sie gesehen hat", "tag": "[Heilkunde]", "probe": {"id": "heilkunde", "dc": 13}, "erfolg": {"text": "Zittern, Erbrechen, kalte Haut, kaum Fieber, enge Pupillen. Das ist kein Fieber. Das ist Eisenhut, in kleinen Gaben. Jemand vergiftet den Grafen langsam, damit es nach Fieber aussieht.", "weiter": "plan", "folgen": {"flag": ["gift_erkannt"]}}, "misserfolg": {"text": "Klingt schlimm, aber du kannst es nicht deuten.", "weiter": "plan"}}, {"text": "„Kannst du mich zu ihm bringen?“", "weiter": "plan"}]}, "severin": {"ort": "burg", "text": "Severin kniet nicht. Er steht am Altar und packt Bücher in eine Kiste, als wolle er fliehen. „Das Testament“, sagt er, als er dich sieht, ohne Begrüßung. „Der Graf hat es mir anvertraut. Gerlinde soll die Grafschaft erben. Ragnolf weiß es. Wenn er es findet, verbrennt er es, und dann gilt das alte Recht: Der Vogt verwaltet, bis ein Erbe kommt. Er wird dafür sorgen, dass keiner kommt.“", "optionen": [{"text": "„Gib mir das Testament. Ich bringe es in Sicherheit.“", "weiter": "testament"}, {"text": "„Warum fliehst du nicht damit?“", "weiter": "severin2"}]}, "severin2": {"ort": "burg", "text": "Severin lacht unglücklich. „Weil ich ein Feigling bin. Ich habe Ragnolf die Beichte abgenommen – ich weiß, was er vorhat, seit Wochen. Und ich habe nichts getan.“ Er drückt dir ein versiegeltes Pergament in die Hand. „Tu du es.“", "optionen": [{"text": "Das Testament nehmen", "weiter": "plan", "folgen": {"flag": ["testament"]}}]}, "testament": {"ort": "burg", "text": "Severin zögert, dann gibt er dir ein versiegeltes Pergament. „Das Siegel des Grafen. Gerlinde muss es vor Zeugen öffnen.“", "optionen": [{"text": "Es sicher verstauen", "weiter": "plan", "folgen": {"flag": ["testament"]}}]}, "plan": {"ort": "burg", "text": "Die Nacht kommt früh auf dem Felsen. Irgendwo oben stirbt ein alter Mann – oder wird getötet. Die Graumäntel stehen an den Treppen. Gerlinde ist Tage entfernt. Was jetzt geschieht, entscheidet über Rabenfels.", "optionen": [{"text": "In den Turm schleichen, zum Grafen", "weiter": "turm"}, {"text": "Reiter nach Kloster Morgenstern schicken, damit Gerlinde kommt", "weiter": "bote"}, {"text": "Ragnolf direkt zur Rede stellen", "weiter": "ragnolf"}]}, "bote": {"ort": "burg", "text": "Im Stall findest du einen Burschen, Gunthram, der für ein paar Münzen jedes Pferd reitet. „Morgenstern? Zwei Tage. Wenn die Graumäntel mich nicht vorher erwischen.“", "optionen": [{"text": "Ihn mit genug Mut ausstatten, dass er reitet", "tag": "[Überreden]", "probe": {"id": "ueberreden", "dc": 12}, "erfolg": {"text": "Er nickt, blass. Minuten später hörst du Hufe auf dem Felsweg. Ob er durchkommt, wirst du erst später erfahren.", "weiter": "turm", "folgen": {"flag": ["bote"]}}, "misserfolg": {"text": "„Nein. Ich will leben.“ Er verschwindet im Heu.", "weiter": "turm"}}]}, "turm": {"ort": "burg", "text": "Der Turm wird bewacht, aber die Wachen schauen nach außen, nicht nach innen. Ein alter Abwurfschacht für Küchenabfälle führt nach oben.", "minispiel": {"art": "seil", "schwer": 3, "titel": "Durch den Schacht klettern", "erfolg": {"text": "Du kommst oben heraus, verdreckt, in einer Kammer neben dem Schlafgemach. Durch die Tür hörst du schweres Atmen. Und eine leise Stimme: Ragnolf.", "weiter": "gemach"}, "misserfolg": {"text": "Du rutschst ab, Lärm. Schritte. Du musst dich verstecken – und siehst nur noch, wie Ragnolf aus dem Gemach kommt und die Tür absperrt.", "weiter": "ragnolf", "folgen": {"flag": ["entdeckt"]}}}, "optionen": []}, "gemach": {"ort": "burg", "text": "Ragnolf sitzt am Bett des Grafen. Er hält ihm einen Becher an die Lippen, sanft wie eine Amme. „Trink, Herr. Bald ist es vorbei.“ Der alte Mann trinkt. Ragnolf steht auf, geht hinaus, ohne dich zu bemerken. Der Graf sieht dich aus dem Halbdunkel an. Er weiß nicht, wer du bist. Aber er weiß, was in dem Becher war.", "optionen": [{"text": "Dem Grafen helfen, das Gift loszuwerden", "tag": "[Heilkunde]", "probe": {"id": "heilkunde", "dc": 13, "mod": {"gift_erkannt": -3}}, "erfolg": {"text": "Salzwasser, ein Finger im Hals, Kohle aus dem Kamin. Würdelos, aber es wirkt. Der Graf ist schwach – aber er wird diese Nacht überleben. „Wer bist du?“ – „Jemand, der nicht will, dass es so endet.“", "weiter": "graf_lebt", "folgen": {"flag": ["graf_gerettet"]}}, "misserfolg": {"text": "Du tust, was du kannst. Es reicht nicht. Der Graf greift nach deiner Hand und flüstert: „Gerlinde.“ Dann ist er still.", "weiter": "graf_tot"}}, {"text": "Den Becher als Beweis an dich nehmen und verschwinden", "weiter": "graf_tot", "folgen": {"flag": ["becher"]}}]}, "graf_lebt": {"ort": "burg", "text": "Der Graf richtet sich mühsam auf. „Ragnolf.“ Er sagt den Namen wie ein Fluch und wie eine Trauer. „Dreißig Jahre.“ Draußen auf der Treppe Schritte, viele.", "optionen": [{"text": "„Ihr müsst Euch zeigen, Herr. Vor allen. Heute Nacht noch.“", "weiter": "saal"}, {"text": "Den Grafen verstecken, bis Gerlinde kommt", "weiter": "versteck"}]}, "graf_tot": {"ort": "burg", "text": "Die Glocken läuten jetzt schneller. Der Graf ist tot. Ragnolf wird im Morgengrauen vor dem versammelten Hof sprechen – als Verwalter, als Trauernder, als neuer Herr.", "optionen": [{"text": "Vor dem Hof das Testament verlesen", "wenn": {"flag": "testament"}, "weiter": "saal_testament"}, {"text": "Vor dem Hof den Giftbecher zeigen", "wenn": {"flag": "becher"}, "weiter": "saal_becher"}, {"text": "Fliehen, solange es noch geht", "weiter": "ende_ragnolf"}, {"text": "Ragnolf zur Rede stellen", "weiter": "ragnolf"}]}, "ragnolf": {"ort": "burg", "text": "Ragnolf empfängt dich in der Wachstube, als hätte er dich erwartet. Er spricht so leise, dass du dich vorbeugen musst. „Du bist der aus dem Hügelland. Der mit dem Ring des Königs, oder der ohne – das ist mir gleich.“ Er schenkt dir Wein ein. „Rabenfels braucht einen starken Herrn. Gerlinde ist eine Klosterfrau. Ich habe dreißig Jahre dieses Land regiert, während Wulfhard Hirsche jagte. Hilf mir, und das Hügelland ist frei von Abgaben, solange ich lebe.“", "optionen": [{"text": "„Ich nehme an.“", "weiter": "ende_ragnolf_hilfe"}, {"text": "„Du hast deinen Herrn vergiftet. Kein Mensch folgt einem Giftmischer.“", "tag": "[Einschüchtern]", "probe": {"id": "einschuechtern", "dc": 15}, "erfolg": {"text": "Für einen Herzschlag verliert Ragnolf die Fassung. Dann lächelt er. „Beweise es.“ Aber du hast gesehen, dass er Angst hat.", "weiter": "saal", "folgen": {"flag": ["ragnolf_wankt"]}}, "misserfolg": {"text": "„Wer hat das gesagt? Die Magd?“ Er winkt die Wachen. Du entkommst, aber Wiebke wird heute Nacht nicht mehr in der Küche sein.", "weiter": "saal", "folgen": {"flag": ["wiebke_gefangen"]}}, "wenn": {"flag": "gift_erkannt"}}, {"text": "Wortlos aufstehen und gehen", "weiter": "saal"}]}, "versteck": {"ort": "burg", "text": "Ihr bringt den Grafen in Severins Sakristei. Drei Tage. Drei Tage, in denen Ragnolf die Burg durchsucht und erzählt, der Graf sei im Fieber in den Felsen gestürzt. Am dritten Abend Hufe auf dem Felsweg.", "optionen": [{"text": "Hinaus, um zu sehen, wer kommt", "weiter": "ankunft"}]}, "ankunft": {"ort": "burg", "text": "Ob Reiter kommen, hängt davon ab, ob dein Bote durchgekommen ist. Hufe auf dem Felsweg – viele. Ragnolfs Graumäntel stehen am Tor.", "optionen": [{"text": "Den Grafen auf die Mauer führen, damit alle ihn sehen", "weiter": "ende_wulfhard"}, {"text": "Kämpfen, um das Tor zu öffnen", "weiter": "kampf"}]}, "saal": {"ort": "burg", "text": "Der große Saal im Morgengrauen. Der ganze Hof ist da, Ritter, Mägde, Graumäntel an den Wänden. Ragnolf steht vor dem leeren Stuhl des Grafen und hebt die Hand. „Unser Herr …“", "optionen": [{"text": "Den Grafen hereinführen", "wenn": {"flag": "graf_gerettet"}, "weiter": "ende_wulfhard"}, {"text": "Das Testament verlesen", "wenn": {"flag": "testament"}, "weiter": "saal_testament"}, {"text": "Zur Waffe greifen", "weiter": "kampf"}, {"text": "Schweigen", "weiter": "ende_ragnolf"}]}, "saal_testament": {"ort": "burg", "text": "Du trittst vor und brichst das Siegel. Gerlinde soll erben. Ein Raunen geht durch den Saal. Ragnolf lacht leise. „Ein Fremder mit einem Pergament. Wer sagt, dass das echt ist?“", "optionen": [{"text": "Den Hof überzeugen: das Siegel, Severins Zeugnis, Ragnolfs Hast", "tag": "[Überreden]", "probe": {"id": "ueberreden", "dc": 14, "mod": {"ragnolf_wankt": -2}}, "erfolg": {"text": "Severin tritt neben dich, zitternd, und sagt laut: „Ich war dabei, als der Graf es siegelte.“ Ein Ritter nach dem anderen tritt von Ragnolf weg.", "weiter": "ende_gerlinde"}, "misserfolg": {"text": "Zu viele Graumäntel, zu wenig Mut. Die Ritter sehen weg.", "weiter": "kampf"}}]}, "saal_becher": {"ort": "burg", "text": "Du hebst den Becher hoch. „Riecht daran. Eisenhut. Der Vogt hat ihn eigenhändig eingeschenkt.“ Totenstille. Dann ruft Ragnolf: „Ergreift den Mörder!“ – und meint dich.", "optionen": [{"text": "Ruhig bleiben und den Bader rufen lassen, damit er riecht", "tag": "[Beruhigen]", "probe": {"id": "beruhigen", "dc": 13}, "erfolg": {"text": "Der Bader riecht, wird bleich und nickt. Die Graumäntel sehen einander an. Niemand will für einen Giftmischer sterben. Ragnolf zieht sein Schwert – allein.", "weiter": "ende_gerlinde"}, "misserfolg": {"text": "Die Wachen packen dich. Ein Graumantel lächelt.", "weiter": "kampf"}}]}, "kampf": {"ort": "burg", "text": "Graumäntel, zwei Klingen jeder. Ragnolf gibt leise Befehle.", "gefahr": true, "minispiel": {"art": "kampf", "schwer": 3, "titel": "Die Nacht der Raben", "gegner": "banditen", "dauer": 540, "kampfort": "burg", "erfolg": {"text": "Die Graumäntel fliehen über die Mauer, als ihr Sold nicht mehr sicher ist. Ragnolf liegt verwundet im Saal. Der Hof sieht dich an.", "weiter": "nach_kampf"}, "misserfolg": {"text": "Du wirst über die Mauer geworfen und überlebst den Sturz nur knapp. Als du wieder zu dir kommst, wehen über Rabenfels schwarze Fahnen mit einem Raben.", "weiter": "ende_ragnolf", "folgen": {"gefahr": 2}}}, "optionen": []}, "nach_kampf": {"ort": "burg", "text": "Ragnolf blutet. „Mach schon“, sagt er. „Oder lass es. Ohne mich zerfällt Rabenfels in einem Jahr.“", "optionen": [{"text": "Ihn dem Hof übergeben und auf Gerlinde warten", "weiter": "ende_gerlinde"}, {"text": "Ihn laufen lassen – Rabenfels soll sein Blut nicht brauchen", "weiter": "ende_gerlinde_gnade"}]}, "ende_wulfhard": {"ort": "burg", "text": "Der alte Graf steht auf der Mauer, gestützt auf deine Schulter, grau wie sein Beiname. Unten fällt der Hof auf die Knie. Ragnolf wird noch in derselben Stunde in Ketten gelegt. Wulfhard sieht lange auf die Ketten. Dann sagt er nur: „Dreißig Jahre.“ Er wird nicht mehr lange leben, das weiß jeder. Aber er wird nicht ermordet sterben.", "ende": true, "folgen": {"chronik": ["nacht_wulfhard", "Ich habe Graf Wulfhard vor dem Gift seines Vogts gerettet."], "beute": {"stufe": 2, "text": "Graf Wulfhard nimmt einen Ring von seiner Hand:"}, "welt_kanon": {"key": "rabenfels_nacht", "kanon_titel": "Die Nacht der Raben: Graf Wulfhard überlebt den Giftanschlag seines Vogts Ragnolf", "tat": {"art": "kanon", "ort": "rabenfels", "gross": 3, "titel": "Der Vogt von Rabenfels in Ketten", "text": "{held} aus {dorf} hat in Rabenfels den Giftanschlag des Burgvogts Ragnolf auf Graf Wulfhard vereitelt. Der Graf lebt, Ragnolf sitzt im Kerker, die Graumäntel sind aus der Burg geflohen.", "geruecht": "In Rabenfels soll der Vogt den alten Grafen vergiftet haben – und ein Fremder aus dem Hügelland hat ihn aufgehalten, heißt es."}, "fakten": {"ragnolf": "kerker", "herr": "wulfhard"}, "bez": [{"a": "rabenfels", "b": "moosherz", "art": "nachbar", "grund": "Seit der Nacht der Raben vorsichtige Annäherung"}, {"a": "kraehenstieg", "b": "rabenfels", "art": "rivalitaet", "grund": "Die Graumäntel haben in Rabenfels verloren"}]}}}, "ende_gerlinde": {"ort": "burg", "text": "Zwei Tage später reitet Gerlinde durch das Tor von Rabenfels, in grauem Klostergewand, mit kurzgeschorenem Haar. Sie geht wortlos an Ragnolf in seinen Ketten vorbei und setzt sich auf den Stuhl ihres Vaters. Ihre erste Anordnung: Die Grenze wird für Ärzte und Korn geöffnet, nicht für Soldaten. Ihre zweite: Der Vogt wird nicht gehängt. Er wird in das Kloster geschickt, in ihre alte Zelle.", "ende": true, "folgen": {"chronik": ["nacht_gerlinde", "Ich habe geholfen, dass Gerlinde Gräfin von Rabenfels wurde."], "beute": {"stufe": 2, "text": "Gräfin Gerlinde lässt dir überreichen:"}, "welt_kanon": {"key": "rabenfels_nacht", "kanon_titel": "Die Nacht der Raben: Gerlinde wird Gräfin von Rabenfels", "tat": {"art": "herrscher", "ort": "rabenfels", "gross": 3, "titel": "Gräfin Gerlinde herrscht in Rabenfels", "text": "In Rabenfels ist Graf Wulfhard gestorben, vergiftet von seinem Vogt Ragnolf. Doch {held} aus {dorf} hat das Testament gerettet: Seine Tochter Gerlinde ist jetzt Gräfin. Sie öffnet die Grenze für Ärzte und Korn.", "geruecht": "Rabenfels hat eine Herrin, eine Nonne, sagt man. Und der alte Vogt sitzt in einer Klosterzelle."}, "herrscher": {"reich": "rabenfels", "name": "Gräfin Gerlinde"}, "fakten": {"ragnolf": "kloster", "herr": "gerlinde", "wulfhard": "tot"}, "bez": [{"a": "rabenfels", "b": "moosherz", "art": "handel", "grund": "Gräfin Gerlinde öffnet die Grenze für Korn und Arznei"}, {"a": "kraehenstieg", "b": "rabenfels", "art": "rivalitaet", "grund": "Die Graumäntel haben in Rabenfels verloren"}]}}}, "ende_gerlinde_gnade": {"ort": "burg", "text": "Ragnolf humpelt in die Nacht hinaus, ohne sich umzudrehen. Gerlinde kommt zwei Tage später und wird Gräfin. Als sie hört, dass du den Vogt hast gehen lassen, sieht sie dich lange an. „Mein Vater hätte ihn hängen lassen“, sagt sie. „Und ich hätte ihn dafür gehasst.“ Irgendwo jenseits der Grenze lebt jetzt ein Mann, der dreißig Jahre Macht verloren hat.", "ende": true, "folgen": {"chronik": ["nacht_gnade", "Ich habe Ragnolf gehen lassen. Gerlinde ist Gräfin."], "beute": {"stufe": 1}, "welt_kanon": {"key": "rabenfels_nacht", "kanon_titel": "Die Nacht der Raben: Gerlinde wird Gräfin, Ragnolf flieht", "tat": {"art": "herrscher", "ort": "rabenfels", "gross": 3, "titel": "Gräfin Gerlinde herrscht in Rabenfels – der Vogt ist auf der Flucht", "text": "Graf Wulfhard ist tot, vergiftet. Seine Tochter Gerlinde ist Gräfin von Rabenfels. Der Vogt Ragnolf ist geflohen – {held} aus {dorf} soll ihn haben gehen lassen.", "geruecht": "Der Rabe von Rabenfels ist ausgeflogen, sagt man. Niemand weiß, wohin."}, "herrscher": {"reich": "rabenfels", "name": "Gräfin Gerlinde"}, "fakten": {"ragnolf": "flucht", "herr": "gerlinde", "wulfhard": "tot"}, "bez": [{"a": "rabenfels", "b": "moosherz", "art": "handel", "grund": "Gräfin Gerlinde öffnet die Grenze für Korn und Arznei"}]}}}, "ende_ragnolf": {"ort": "burg", "text": "Im Morgengrauen spricht Ragnolf zum Hof. Er trauert glaubhaft um seinen Herrn. Er verspricht Ordnung, Brot und Stärke. Über dem Tor hängen sie eine neue Fahne auf: ein schwarzer Rabe auf grauem Grund. Gerlinde wird nie in Rabenfels ankommen. Man wird erzählen, sie sei auf dem Weg im Fieber gestorben.", "ende": true, "folgen": {"chronik": ["nacht_ragnolf", "Ragnolf hat in Rabenfels die Macht ergriffen. Ich war dabei und konnte es nicht verhindern."], "welt_kanon": {"key": "rabenfels_nacht", "kanon_titel": "Die Nacht der Raben: Burgvogt Ragnolf reißt Rabenfels an sich", "tat": {"art": "herrscher", "ort": "rabenfels", "gross": 3, "titel": "Der Rabe herrscht in Rabenfels", "text": "Graf Wulfhard von Rabenfels ist tot. Sein Burgvogt Ragnolf hat die Grafschaft an sich gerissen; über dem Tor weht ein schwarzer Rabe. Die Graumäntel aus Krähenstieg stehen jetzt in seinem Sold. Moosherz ist in Sorge.", "geruecht": "Der alte Graf ist tot, und ein Rabe sitzt auf seinem Stuhl, heißt es. Man sagt, er hat ihn vergiftet."}, "herrscher": {"reich": "rabenfels", "name": "Ragnolf der Rabe"}, "fakten": {"ragnolf": "herrscher", "herr": "ragnolf", "wulfhard": "tot"}, "bez": [{"a": "rabenfels", "b": "moosherz", "art": "rivalitaet", "grund": "Der Rabe von Rabenfels rüstet gegen Moosherz"}, {"a": "kraehenstieg", "b": "rabenfels", "art": "buendnis", "grund": "Die Graumäntel dienen dem Raben"}]}}}, "ende_ragnolf_hilfe": {"ort": "burg", "text": "Du hilfst Ragnolf, die Nacht zu überstehen. Am Morgen weht über Rabenfels die Fahne mit dem schwarzen Raben, und in deiner Tasche liegt ein Brief mit Rabensiegel: Das Hügelland zahlt keine Abgaben, solange Ragnolf lebt. Er wird lange leben wollen. Und er wird sich erinnern, wer ihm geholfen hat – und dass so jemand auch anderen helfen könnte.", "ende": true, "folgen": {"chronik": ["nacht_ragnolf_hilfe", "Ich habe Ragnolf geholfen, Herr von Rabenfels zu werden."], "beute": {"stufe": 2, "text": "Ragnolf hält Wort und lässt dir bringen:"}, "welt_kanon": {"key": "rabenfels_nacht", "kanon_titel": "Die Nacht der Raben: Burgvogt Ragnolf reißt Rabenfels an sich – mit Hilfe aus dem Hügelland", "tat": {"art": "herrscher", "ort": "rabenfels", "gross": 3, "titel": "Der Rabe herrscht in Rabenfels", "text": "Graf Wulfhard von Rabenfels ist tot. Sein Burgvogt Ragnolf hat die Grafschaft an sich gerissen, und man sagt, {held} aus {dorf} habe ihm dabei geholfen. Über dem Tor weht ein schwarzer Rabe.", "geruecht": "Der Rabe sitzt auf dem Grafenstuhl, und Hügelländer haben ihm die Leiter gehalten, flüstert man."}, "herrscher": {"reich": "rabenfels", "name": "Ragnolf der Rabe"}, "fakten": {"ragnolf": "herrscher", "herr": "ragnolf", "wulfhard": "tot"}, "bez": [{"a": "rabenfels", "b": "moosherz", "art": "rivalitaet", "grund": "Der Rabe von Rabenfels rüstet gegen Moosherz"}, {"a": "kraehenstieg", "b": "rabenfels", "art": "buendnis", "grund": "Die Graumäntel dienen dem Raben"}]}}}}, "kanon": "rabenfels_nacht"}}, {"id": "w_kammwacht", "titel": "Die Schlacht um Kammwacht", "kurz": "König Ottokar ruft den Heerbann: Die Feste Kammwacht, im Grenzkrieg verloren, soll zurück. Was dort geschieht, wird überall erzählt werden.", "schwer": 3, "fundort": null, "def": {"start": "start", "szenen": {"start": {"ort": "dorf", "text": "Ein königlicher Reiter mit dem goldenen Hirsch auf dem Mantel hält auf dem Dorfplatz und liest vor: „König Ottokar ruft den Heerbann. Kammwacht, die Feste, die uns im Grenzkrieg genommen wurde, soll zurück ins Königreich. Wer eine Waffe tragen kann, sammle sich in Hollerbrück.“ Dann reitet er weiter. Auf dem Platz ist es still. Ein paar Alte sehen zu Boden. Sie waren schon einmal bei Kammwacht.", "optionen": [{"text": "Sich dem Heerbann anschließen", "weiter": "aufbruch"}, {"text": "Erst mit einem der Alten reden", "weiter": "alte"}]}, "alte": {"ort": "dorf", "text": "Der alte Zimmermann spuckt aus. „Kammwacht. Da haben sie uns damals hingeschickt, junge Kerle, und wer zurückkam, kam als ein anderer zurück. Es gibt dort eine Scheune. Gab. Frag nicht.“ Er sieht dich an. „Wenn du gehst, dann komm als derselbe zurück.“", "optionen": [{"text": "Aufbrechen", "weiter": "aufbruch", "folgen": {"flag": ["scheune_erinnert"]}}]}, "aufbruch": {"ort": "wald", "text": "Der Weg nach Osten führt über Hollerbrück, wo das Heer sich sammelt, und dann hinauf in die Vorberge des Ostkamms.", "reise": {"minuten": 240, "weiter": "lager", "text": "Du ziehst mit dem Heerbann nach Osten."}}, "lager": {"ort": "feuer", "text": "Das Heerlager vor Kammwacht: tausend Feuer, Pferdemist, Gebete. Hauptmann Bruno aus Moosherz führt die Hügelländer. Die Feste thront auf einem Grat, die Mauern grau, oben die Fahne der Ostmark. „Morgen früh stürmen wir“, sagt Bruno. „Der Herzog Ansgar führt den Angriff. Er hat Befehl gegeben: Wer sich nicht ergibt, wird nicht geschont. Auch die im Dorf unter der Feste nicht.“", "optionen": [{"text": "„Das Dorf? Da leben Bauern.“", "weiter": "befehl"}, {"text": "Die Mauern auskundschaften", "weiter": "kundschaft"}, {"text": "Nachts ins Dorf unter der Feste schleichen", "weiter": "dorf_nacht"}]}, "befehl": {"ort": "feuer", "text": "Bruno sieht dich lange an. „Ich war vor zwanzig Jahren hier. Ich weiß, was du meinst.“ Er senkt die Stimme. „Ansgar will Rache für den Grenzkrieg und ein Exempel. Wenn die Feste fällt, bevor er das Dorf erreicht, gibt es nichts mehr zu strafen.“", "optionen": [{"text": "„Dann muss die Feste schnell fallen. Ohne Blutbad.“", "weiter": "kundschaft", "folgen": {"flag": ["bruno_verbuendet"]}}, {"text": "„Befehl ist Befehl.“", "weiter": "sturm"}]}, "kundschaft": {"ort": "berg", "text": "Im Morgennebel kriechst du am Grat entlang. Die Mauern sind alt, an der Nordseite bröckelt der Mörtel. Und dort, eine Pforte für Wasserträger, kaum bewacht.", "minispiel": {"art": "spuren", "schwer": 3, "titel": "Die Mauern lesen", "erfolg": {"text": "Die Wasserpforte. Durch sie kämen zwanzig Mann in die Feste, bevor jemand Alarm schlägt.", "weiter": "entscheidung", "folgen": {"flag": ["pforte"]}}, "misserfolg": {"text": "Nebel, Fels, Wachen. Nichts, was einen Sturm überflüssig macht.", "weiter": "entscheidung"}}, "optionen": []}, "dorf_nacht": {"ort": "dorf", "text": "Das Dorf unter der Feste: zwanzig Häuser, Weinstöcke, Kinder, die im Schlaf husten. Eine alte Frau steht vor ihrer Tür und sieht dich an, als wüsste sie, wer du bist. „Ihr kommt also wieder“, sagt sie. „Beim letzten Mal habt ihr meine Schwester in einer Scheune verbrannt.“", "optionen": [{"text": "„Ich bin nicht gekommen, um zu verbrennen. Wer führt die Feste?“", "tag": "[Menschenkenntnis]", "probe": {"id": "menschenkenntnis", "dc": 12}, "erfolg": {"text": "Sie mustert dich, dann redet sie: „Kommandant Leuthold. Ein alter Mann. Er will nicht sterben für eine Markgräfin, die ihm seit einem Jahr keinen Sold schickt. Er würde reden – wenn ihm jemand das Leben seiner Leute verspricht.“", "weiter": "entscheidung", "folgen": {"flag": ["leuthold"]}}, "misserfolg": {"text": "Sie schließt die Tür vor deiner Nase.", "weiter": "entscheidung"}}, {"text": "Leise wieder gehen", "weiter": "entscheidung"}]}, "entscheidung": {"ort": "feuer", "text": "Das Morgengrauen färbt den Grat rot. Die Hörner blasen. Ansgars Ritter sitzen auf. Was jetzt geschieht, wird in Moosherz und in Brandenstein erzählt werden – und in jeder Schenke dazwischen.", "optionen": [{"text": "Mit zwanzig Hügelländern durch die Wasserpforte, bevor der Sturm beginnt", "wenn": {"flag": "pforte"}, "weiter": "pforte"}, {"text": "Zu Kommandant Leuthold gehen und um Übergabe verhandeln", "wenn": {"flag": "leuthold"}, "weiter": "leuthold"}, {"text": "Mit dem Heer stürmen", "weiter": "sturm"}, {"text": "Bruno überreden, Ansgar aufzuhalten, und einen Frieden vorschlagen", "weiter": "frieden"}]}, "pforte": {"ort": "berg", "text": "Ein schmaler Gang, nasser Stein, dann der Hof der Feste. Die Verteidiger rennen zu den Mauern – und finden euch hinter sich.", "gefahr": true, "minispiel": {"art": "kampf", "schwer": 3, "titel": "In der Feste Kammwacht", "gegner": "banditen", "dauer": 480, "kampfort": "berg", "erfolg": {"text": "Das Tor schwingt von innen auf, bevor Ansgars Ritter es erreichen. Die Besatzung legt die Waffen nieder. Auf dem Turm reißt jemand die Fahne der Ostmark herunter.", "weiter": "nach_fall"}, "misserfolg": {"text": "Ihr werdet in den Hof zurückgedrängt. Draußen beginnt der Sturm, und er wird lang und blutig.", "weiter": "sturm_blutig", "folgen": {"gefahr": 1}}}, "optionen": []}, "leuthold": {"ort": "burg", "text": "Leuthold ist ein müder Mann mit grauem Bart, der dich in seiner Kammer empfängt, das Schwert auf dem Tisch. „Sie wollen also die Feste. Und was bekommen meine Leute?“", "optionen": [{"text": "„Freien Abzug mit Waffen und Ehre. Und das Dorf bleibt unberührt – mein Wort und das von Hauptmann Bruno.“", "tag": "[Überreden]", "probe": {"id": "ueberreden", "dc": 14, "mod": {"bruno_verbuendet": -2}}, "erfolg": {"text": "Er schweigt lange. „Ein Wort aus dem Hügelland.“ Dann steht er auf. „Gut. Ich öffne das Tor bei Sonnenaufgang. Wenn dein Herzog trotzdem ins Dorf reitet, komme ich zurück und hole dich.“", "weiter": "uebergabe"}, "misserfolg": {"text": "„Worte. Ansgar hat schon einmal Worte gebrochen.“ Er lässt dich hinausbringen.", "weiter": "sturm"}}]}, "frieden": {"ort": "feuer", "text": "Bruno hört dich an, dann geht er mit dir zu Ansgar. Der Herzog lacht. Aber im Zelt sitzt auch ein Gesandter des Salzbundes, der nur offene Straßen will, und eine Botin der Markgräfin Ysolde, die schon seit Tagen wartet.", "optionen": [{"text": "„Kammwacht bleibt bei der Ostmark – aber der Weg über den Pass wird frei für Moosherzer Händler, und die Ostmark zahlt für zwanzig Jahre Zoll.“", "tag": "[Feilschen]", "probe": {"id": "feilschen", "dc": 15}, "erfolg": {"text": "Die Botin der Ostmark nickt langsam. Der Salzbund-Gesandte klatscht in die Hände. Ansgar flucht, aber er weiß, dass der König Geld lieber mag als Gräber.", "weiter": "ende_frieden"}, "misserfolg": {"text": "Ansgar wirft dich aus dem Zelt. „Bauern sollen kämpfen, nicht reden.“", "weiter": "sturm"}}]}, "sturm": {"ort": "berg", "text": "Leitern an den Mauern, Pech von oben, Schreie. Du kletterst mit den Hügelländern hinauf.", "gefahr": true, "minispiel": {"art": "kampf", "schwer": 3, "titel": "Sturm auf Kammwacht", "gegner": "banditen", "dauer": 660, "kampfort": "berg", "erfolg": {"text": "Ihr seid auf der Mauer. Die Verteidiger weichen zurück, dann fliehen sie. Kammwacht fällt.", "weiter": "nach_fall"}, "misserfolg": {"text": "Die Leitern brechen, der Sturm scheitert. Bei Sonnenuntergang zieht sich das Heer zurück. Kammwacht hält.", "weiter": "ende_niederlage", "folgen": {"gefahr": 2}}}, "optionen": []}, "sturm_blutig": {"ort": "berg", "text": "Ihr kämpft im Hof, während draußen die Ritter gegen das Tor rennen.", "gefahr": true, "minispiel": {"art": "kampf", "schwer": 3, "titel": "Der lange Sturm", "gegner": "banditen", "dauer": 420, "kampfort": "berg", "erfolg": {"text": "Am Abend fällt die Feste – teuer erkauft.", "weiter": "nach_fall"}, "misserfolg": {"text": "Kammwacht hält. Das Heer zieht ab.", "weiter": "ende_niederlage", "folgen": {"gefahr": 2}}}, "optionen": []}, "nach_fall": {"ort": "burg", "text": "Kammwacht ist gefallen. Herzog Ansgar reitet durch das Tor, sieht sich um und zeigt hinunter ins Dorf. „Und jetzt die da unten. Für den Grenzkrieg.“ Seine Ritter wenden die Pferde.", "optionen": [{"text": "Dich mit den Hügelländern in den Weg stellen", "tag": "[Einschüchtern]", "probe": {"id": "einschuechtern", "dc": 14}, "erfolg": {"text": "Zwanzig Bauern mit blutigen Äxten stehen zwischen den Rittern und dem Dorf. Bruno stellt sich dazu. Ansgar sieht sie an, sieht dich an – und reitet zurück in die Feste. Das Dorf schläft heute Nacht ohne Feuer.", "weiter": "ende_sieg_gnade"}, "misserfolg": {"text": "Die Ritter reiten an euch vorbei. Später brennt im Dorf eine Scheune.", "weiter": "ende_sieg_brand"}}, {"text": "Nichts tun", "weiter": "ende_sieg_brand"}]}, "uebergabe": {"ort": "burg", "text": "Bei Sonnenaufgang öffnet sich das Tor von Kammwacht. Leutholds Leute ziehen ab, die Waffen geschultert, und niemand hält sie auf, weil Bruno und die Hügelländer am Wegrand stehen. Ansgar tobt. Das Dorf unter der Feste bleibt still.", "optionen": [{"text": "Die Feste betreten", "weiter": "ende_uebergabe"}]}, "ende_sieg_gnade": {"ort": "burg", "text": "Über Kammwacht weht wieder der goldene Hirsch. In Moosherz läuten die Glocken, König Ottokar soll geweint haben. Im Dorf unter der Feste bringt dir die alte Frau am nächsten Morgen Brot. Sie sagt nichts. Das muss sie auch nicht.", "ende": true, "folgen": {"chronik": ["kammwacht_gnade", "Kammwacht ist gefallen. Ich habe das Dorf darunter vor Ansgars Rittern geschützt."], "beute": {"stufe": 2, "text": "Hauptmann Bruno drückt dir etwas in die Hand:"}, "welt_kanon": {"key": "kammwacht_schlacht", "kanon_titel": "Die Schlacht um Kammwacht: Moosherz erobert die Feste zurück – das Dorf bleibt verschont", "tat": {"art": "schlacht", "ort": "kammwacht", "gross": 3, "titel": "Kammwacht ist wieder moosherzisch", "text": "Das Heer von König Ottokar hat die Feste Kammwacht im Sturm genommen. Als Herzog Ansgar das Dorf unter der Feste strafen wollte, stellten sich {held} aus {dorf} und die Hügelländer seinen Rittern in den Weg.", "geruecht": "Kammwacht ist gefallen, sagt man, und Bauern aus dem Hügelland haben einem Herzog die Stirn geboten."}, "ort_wechsel": {"ort": "kammwacht", "reich": "moosherz"}, "fakten": {"kammwacht": "moosherz"}, "bez": [{"a": "moosherz", "b": "brandenstein", "art": "rivalitaet", "grund": "Kammwacht ist wieder moosherzisch"}]}}}, "ende_sieg_brand": {"ort": "burg", "text": "Über Kammwacht weht der goldene Hirsch. Im Dorf darunter brennt eine Scheune, und diesmal hat niemand die Tür zugehalten, weil niemand mehr drin war – die Leute sind in die Weinberge geflohen. Ansgar lässt sich in Moosherz feiern. Die Ostmark wird das nicht vergessen.", "ende": true, "folgen": {"chronik": ["kammwacht_brand", "Kammwacht ist gefallen. Das Dorf darunter hat gebrannt."], "beute": {"stufe": 1}, "welt_kanon": {"key": "kammwacht_schlacht", "kanon_titel": "Die Schlacht um Kammwacht: Moosherz erobert die Feste zurück, das Dorf darunter brennt", "tat": {"art": "schlacht", "ort": "kammwacht", "gross": 3, "titel": "Kammwacht ist gefallen – und das Dorf brennt", "text": "Das Heer von König Ottokar hat die Feste Kammwacht zurückerobert. Herzog Ansgars Ritter haben danach das Dorf unter der Feste in Brand gesteckt. In der Ostmark schwört man Rache.", "geruecht": "Wieder brennt es bei Kammwacht, erzählt man. Manche Dinge ändern sich nie."}, "ort_wechsel": {"ort": "kammwacht", "reich": "moosherz"}, "fakten": {"kammwacht": "moosherz", "dorf_verbrannt": true}, "bez": [{"a": "moosherz", "b": "brandenstein", "art": "rivalitaet", "grund": "Das Dorf bei Kammwacht brannte"}]}}}, "ende_uebergabe": {"ort": "burg", "text": "Kammwacht gehört wieder zu Moosherz, und kein Tropfen Blut ist geflossen. In Moosherz nennen sie es eine Schande – eine Feste ohne Sturm. In den Dörfern beiderseits der Grenze nennen sie es ein Wunder. Leuthold schickt dir einen Brief aus Brandenstein: „Du hast Wort gehalten. Das ist selten.“", "ende": true, "folgen": {"chronik": ["kammwacht_uebergabe", "Ich habe Kammwacht ohne Blut übergeben lassen."], "beute": {"stufe": 2, "text": "Leutholds Brief liegt etwas bei:"}, "welt_kanon": {"key": "kammwacht_schlacht", "kanon_titel": "Kammwacht: Die Feste wird ohne Kampf an Moosherz übergeben", "tat": {"art": "gebiet", "ort": "kammwacht", "gross": 3, "titel": "Kammwacht ergibt sich ohne Kampf", "text": "Die Feste Kammwacht ist ohne Sturm an König Ottokar gefallen: {held} aus {dorf} hat mit dem Kommandanten Leuthold freien Abzug ausgehandelt. Das Dorf unter der Feste blieb unberührt.", "geruecht": "Eine Feste, die sich ergibt, ohne dass einer stirbt? Das gibt es also doch, erzählt man."}, "ort_wechsel": {"ort": "kammwacht", "reich": "moosherz"}, "fakten": {"kammwacht": "moosherz", "unblutig": true}, "bez": [{"a": "moosherz", "b": "brandenstein", "art": "nachbar", "grund": "Kammwacht wechselte ohne Blut den Herrn"}]}}}, "ende_frieden": {"ort": "feuer", "text": "Es gibt keine Schlacht. Kammwacht bleibt bei der Ostmark, aber über den Pass rollen bald Wagen aus Moosherz, und die Ostmark zahlt. Ansgar reitet wütend heim. Der König, sagt man, habe gelacht, als er von der Abmachung hörte – zum ersten Mal seit Jahren.", "ende": true, "folgen": {"chronik": ["kammwacht_frieden", "Ich habe vor Kammwacht einen Frieden ausgehandelt statt einer Schlacht."], "beute": {"stufe": 2, "text": "Der Gesandte des Salzbundes schenkt dir:"}, "welt_kanon": {"key": "kammwacht_schlacht", "kanon_titel": "Kammwacht: Frieden statt Schlacht – die Ostmark zahlt Zoll an Moosherz", "tat": {"art": "kanon", "ort": "kammwacht", "gross": 3, "titel": "Frieden vor Kammwacht", "text": "Vor Kammwacht gab es keine Schlacht: {held} aus {dorf} hat einen Frieden ausgehandelt. Kammwacht bleibt bei der Ostmark, doch Moosherzer Händler ziehen frei über den Pass, und die Ostmark zahlt zwanzig Jahre Zoll.", "geruecht": "Statt Krieg gibt es jetzt Wagen über den Pass, erzählt man. Der Salzbund reibt sich die Hände."}, "fakten": {"kammwacht": "ostmark", "frieden": true}, "bez": [{"a": "moosherz", "b": "brandenstein", "art": "handel", "grund": "Frieden von Kammwacht: freier Pass und Zoll"}]}}}, "ende_niederlage": {"ort": "wald", "text": "Das Heer zieht ab, geschlagen, die Toten auf Karren. Kammwacht hält. In Brandenstein feiert die Markgräfin. Auf dem Heimweg reden die Hügelländer nicht. Manche werden nie darüber reden, so wie ihre Väter.", "ende": true, "folgen": {"chronik": ["kammwacht_niederlage", "Wir haben vor Kammwacht verloren."], "welt_kanon": {"key": "kammwacht_schlacht", "kanon_titel": "Die Schlacht um Kammwacht: Das Heer des Königs wird zurückgeschlagen", "tat": {"art": "schlacht", "ort": "kammwacht", "gross": 3, "titel": "Niederlage vor Kammwacht", "text": "Das Heer von König Ottokar ist vor Kammwacht gescheitert. Die Feste hält, die Ostmark feiert. Auch {held} aus {dorf} kämpfte auf den Leitern.", "geruecht": "Wieder hat Moosherz bei Kammwacht verloren, erzählt man. Der alte König soll getobt haben."}, "fakten": {"kammwacht": "ostmark", "niederlage": true}, "bez": [{"a": "brandenstein", "b": "moosherz", "art": "furcht", "grund": "Moosherz fürchtet nach Kammwacht die Ostmark"}]}}}}, "kanon": "kammwacht_schlacht", "ziel": "kammwacht"}}]$q$::jsonb) e
on conflict (id) do update set titel = excluded.titel, beschreibung = excluded.beschreibung, kurz = excluded.kurz, art = excluded.art, schwierigkeit = excluded.schwierigkeit, def = excluded.def, fundort = excluded.fundort;
